insert into storage.buckets (id, name, public)
values ('business-logos', 'business-logos', true)
on conflict (id) do nothing;

create policy "anon upload logos" on storage.objects
  for insert to anon with check (bucket_id = 'business-logos');

create policy "anon update logos" on storage.objects
  for update to anon using (bucket_id = 'business-logos') with check (bucket_id = 'business-logos');

create policy "public read logos" on storage.objects
  for select to public using (bucket_id = 'business-logos');
